const x=$input.first().json;
if(x.createDocument!==true)throw new Error('Set createDocument to true after connecting your Google Drive credential.');
if(typeof x.title!=='string'||!x.title.trim()||x.title.length>200)throw new Error('Use a nonempty title up to 200 characters.');
if(typeof x.markdown!=='string'||!x.markdown.trim()||x.markdown.length>500000)throw new Error('Use nonempty Markdown up to 500000 characters.');
if(typeof x.parentFolderId!=='string'||(x.parentFolderId && !/^[A-Za-z0-9_-]+$/.test(x.parentFolderId)))throw new Error('Invalid parent folder ID.');
return [{json:{title:x.title.trim(),markdown:x.markdown,parentFolderId:x.parentFolderId}}];

const x=$input.first().json;
if(typeof x.html!=='string'||!x.html.trim())throw new Error('Markdown conversion returned no HTML.');
const origin=$('Validate document').first().json;
const metadata={name:origin.title,mimeType:'application/vnd.google-apps.document'};
if(origin.parentFolderId)metadata.parents=[origin.parentFolderId];
const boundary='n8n_document_boundary_2026';
if(x.html.includes(boundary)||JSON.stringify(metadata).includes(boundary))throw new Error('Document conflicts with MIME boundary.');
const body='--'+boundary+'
Content-Type: application/json; charset=UTF-8

'+JSON.stringify(metadata)+'
--'+boundary+'
Content-Type: text/html; charset=UTF-8

'+x.html+'
--'+boundary+'--
';
return [{json:{body,contentType:'multipart/related; boundary='+boundary}}];

const x=$input.first().json;
if(typeof x.id!=='string'||!/^[A-Za-z0-9_-]+$/.test(x.id))throw new Error('Google did not return a document ID. Check Drive before retrying.');
return [{json:{id:x.id}}];

const x=$input.first().json,expected=$('Validate created document').first().json.id;
if(x.id!==expected||x.mimeType!=='application/vnd.google-apps.document'||x.trashed!==false)throw new Error('Document readback did not match the created Google Doc.');
return [{json:{documentId:x.id,title:x.name,url:'https://docs.google.com/document/d/'+x.id+'/edit',metadataVerified:true,contentRenderingVerified:false}}];
